\title{Dissipative corrections to the particle momentum spectrum of a decoupling fluid} 


\author{Francesco Becattini}
\affiliation{Universit\`a degli studi di Firenze and INFN Sezione di Firenze,\\
Via G. Sansone 1, I-50019 Sesto Fiorentino (Florence), Italy}

\author{Daniele Roselli}
\affiliation{Universit\`a degli studi di Firenze and INFN Sezione di Firenze,\\
Via G. Sansone 1, I-50019 Sesto Fiorentino (Florence), Italy}

\author{Xin-Li Sheng}
\affiliation{Universit\`a degli studi di Firenze and INFN Sezione di Firenze,\\
Via G. Sansone 1, I-50019 Sesto Fiorentino (Florence), Italy}
\affiliation{Institut f\"{u}r Theoretische Physik, Johann Wolfgang Goethe-Universit\"{a}t,
Max-von-Laue-Str.~1, D-60438 Frankfurt am Main, Germany}
\affiliation{ExtreMe Matter Institute EMMI,
GSI Helmholtzzentrum f\"{u}r Schwerionenforschung GmbH,
Planckstrasse 1, 64291 Darmstadt, Germany}

\begin{abstract}
We present an \emph{ab initio} calculation within quantum statistical field theory and linear response theory,
of the dissipative correction to the momentum spectrum of scalar particles emitted at decoupling (freeze-out) from a 
relativistic fluid assuming the initial state to be in local thermodynamic equilibrium. 
We obtain an expansion of the Wigner function of the interacting quantum field in terms of the gradients of the 
classical thermo-hydrodynamic fields - four-temperature vector and reduced chemical potential - evaluated on the 
initial local-equilibrium hypersurface, rather than on the decoupling (freeze-out) hypersurface as usual 
in kinetic theory. The gradient expansion includes an unexpected zeroth order term depending on the differences between 
thermo-hydrodynamic fields at the decoupling and the initial hypersurface. This term encodes a memory of the initial 
state which is related to the long-distance persistence of the correlation function between Wigner operator and stress-energy
tensor and charged current that is discussed in detail. We address the phenomenological implications of these corrections 
for the momentum spectra measured in relativistic nuclear collisions.
\end{abstract}

\maketitle

\label{neqwigner}


We are now going to work out the Wigner function with the method described at the end of the previous Section. According to 
the equation \eqref{lrtO}, we have, with $\wW^+$ given by the equation \eqref{wigner2}:

\begin{equation*}
    \langle \wW^+(x,k)\rangle \simeq \langle\wW^+(x,k)\rangle_{\rm GE}+ \Delta W^+(x,k)\;,
\end{equation*}

where $\Delta W^+(x,k)$ is obtained by replacing $\wO(x)$ with $\wW^+(x,k)$ in the equation 
\eqref{ddO}. The main term $\langle\wW^+(x,k)\rangle_{\rm GE}$ is readily found by using the equation \eqref{wigner2} and the
relations \eqref{tevaa}, \eqref{tevab} and \eqref{tevba}:

\begin{equation}\label{leading order W}
    \langle\wW^+\left(x,k\right)\rangle_{\rm GE}=\frac{2}{\left(2\pi\right)^4}\,
    n_{\rm B}(\beta(x)\cdot k) \, \varrho(k)\;,
\end{equation}

where $\varrho(k)$ is the spectral function calculated with $\wrho$ in \eqref{gedens} with $\beta=\beta(x)$
and $\zeta=\zeta(x)$. Plugging the above expression into the \eqref{Interacting spectrum}, 
integrating in $x$ over the hypersurface of decoupling one obtains the well known relativistic formula for the momentum 
spectrum of particles emitted from a decoupling fluid at local equilibrium, known as Cooper-Frye:

\begin{equation*}
  \frac{\di N_k}{\di^3 \kk} = \frac{2}{(2\pi)^4}\int_0^{+\infty} \di k^0 \; \varrho(k) 
  \int_{\Sigma_{\rm D}} \di\Sigma \cdot k \; n_B (\beta(x) \cdot k)\;,
\end{equation*}

where $\varrho(k)$ encodes the interaction corrections at the decoupling. Note that $k$ is off-shell and $k^2=m^2$ only in 
the limit of free fields for which $\varrho(k)\mapsto\varrho_{\rm free}(k)\propto\delta(k^2-m^2)$.

The calculation of the linear response correction $\Delta W^+(x,k)$ proceeds just like in the ref. \cite{Sheng:2025cjk} 
integrating over the hypersurface $\Sigma_0$ instead of $\Sigma_{\rm D}$ and replacing the free field expansion with
the interacting one in eq. \eqref{intfield}. By using the eq. \eqref{wigner2} and $\wW(x,k)$ replacing $\wO(x)$ in the
eq. \eqref{ddO}:

\begin{align}\label{deltawig1}
 &\Delta W^+(x,k) = - \frac{2}{(2\pi)^5} \int_{\Sigma_{0}} \di \Sigma_{\mu}(y)  
  \int \di^{4}q\;
   \nonumber\\
&\times \Bigg\{\varrho(k_+)\varrho(k_-)\theta(k_+^0)\theta(k_-^0) \e^{\ii x\cdot q}\int_0^1 \di z \, \left\langle 
\wAd (k_+) \wA (k_-), \e^{z\wE_{\rm GE}} \left(
\wT^{\mu\nu}(y) \Delta\beta_\nu(y,x) - \wj^\mu(y) \Delta\zeta(y,x) \right) \e^{-z\wE_{\rm GE}} 
   \right\rangle_{c,{\rm GE}}  \nonumber\\
& + \varrho(k_+)\varrho(-k_-) \theta(k^0_+)\theta(-k^0_-)  \int_0^1 \di z  \left[ \e^{\ii x\cdot q} 
\left\langle \wAd(k_+)\wBd(-k_-),
\e^{z\wE_{\rm GE}} \left(\wT^{\mu\nu}(y) \Delta\beta_\nu(y,x) - \wj^\mu(y) \Delta\zeta(y,x) \right) 
\e^{-z\wE_{\rm GE}} \right\rangle_{c,{\rm GE}} \right. \nonumber \\
& + \left. \left. \e^{-\ii x\cdot q} \left\langle \wB(-k_-)\wA(k_+), \e^{z\wE_{\rm GE}} \left(\wT^{\mu\nu}(y) 
\Delta\beta_\nu(y,x) - \wj^\mu(y) \Delta\zeta(y,x) \right) \e^{-z\wE_{\rm GE}} \right\rangle_{c,{\rm GE}} \right] 
\right\}\;,
\end{align}

with $\wE_{\rm GE}$ as in the equation \eqref{geq}. The equation \eqref{deltawig1} can be further worked out by
extracting exponential factors. Since:

\begin{equation}\label{transtranf}
    \wT^{\mu\nu}(y)=\e^{\ii\wP\cdot y}\,\wT^{\mu\nu}(0)\,\e^{-\ii\wP\cdot y}\;,
    \qquad \wj^{\,\mu}(y)=\e^{\ii\wP\cdot y}\,\wj^{\,\mu}(0)\,\e^{-\ii\wP\cdot y}\;,
\end{equation}

where $\wP$ is the total four-momentum (including interacting terms), and taking into account that the operator 
$\wE_{\rm GE}=-\beta(x)\cdot\wP+\zeta(x)\wQ$ commutes with the generator of translations and the main term of the density 
operator $\e^{\wE_{\rm GE}}/\Tr(\e^{\wE_{\rm GE}})$, we obtain for the $\wAd\wA$ term:

\begin{eqnarray*}
&& \left\langle \wAd (k_+) \wA (k_-),\; \e^{z\wE_{\rm GE}} \left(
   \wT^{\mu\nu}(y) \Delta\beta_\nu(y,x) - \wj^\mu(y) \Delta\zeta(y,x) \right) \e^{-z\wE_{\rm GE}} 
   \right\rangle_{c,{\rm GE}} \\
&& =\left\langle 
\e^{-z\wE_{\rm GE}-iy\cdot\wP}
\wAd (k_+) \wA (k_-)\e^{z\wE_{\rm GE}+iy\cdot\wP} ,\;
   \left( \wT^{\mu\nu}(0) \Delta\beta_\nu(y,x) - \wj^\mu(0) \Delta\zeta(y,x) \right) \right\rangle_{c,{\rm GE}}\;;
\end{eqnarray*}

for the terms involving $\wAd\wBd$ and $\wB\wA$ a similar expression can be derived. By using the transformation properties \eqref{abtransl} and \eqref{abtransl2} and taking into account that $[\wP^\mu,\wQ]=0$, it can be readily shown that the 
quadratic combinations of $\wA$ and $\wB$ operators fulfill the following relations:

\begin{equation*}
 \begin{split}
\e^{-z\wE_{\rm GE}-iy\cdot\wP}\wAd(k_+)\wA(k_-)\e^{z\wE_{\rm GE}+iy\cdot\wP} &=\e^{-\ii y\cdot q }\e^{z\beta(x)\cdot q}\wAd(k_+)\wA(k_-)\;,\\
\e^{-z\wE_{\rm GE}-iy\cdot\wP}\wAd(k_+)\wBd(-k_-)\e^{z\wE_{\rm GE}+iy\cdot\wP} &=\e^{-\ii y\cdot q }\e^{z\beta(x)\cdot q}\wAd(k_+)\wBd(-k_-)\;,\\
\e^{-z\wE_{\rm GE}-iy\cdot\wP}\wB(-k_-)\wA(k_+)\e^{z\wE_{\rm GE}+iy\cdot\wP} &=\e^{\ii y\cdot q }\e^{-z\beta(x)\cdot q}\wB(-k_-)\wA(k_+)\;,
 \end{split}
\end{equation*}

where we used the equality $k_+-k_-=q$ in the equation \eqref{defpm}. Replacing the above expression in 
\eqref{deltawig1} and integrating in $z$ we obtain:

\begin{eqnarray}\label{deltawig2}
&&\Delta W^+(x,k) =\frac{2}{(2\pi)^5} \int_{\Sigma_{0}} \di \Sigma_{\mu}(y) 
\int \di^{4}q\Bigg\{ \varrho(k_+)\varrho(k_-)\frac{1 -\e^{\beta(x)\cdot q}}{\beta(x) \cdot q}
\e^{\ii q\cdot (x-y)}\; \theta(k_+^0)\theta(k_-^0)\nonumber \\
& \times& \left( \left\langle \wAd (k_+) \wA(k_-),\; \wT^{\mu\nu}(0) 
\right\rangle_{c,{\rm GE}} \!\!\! \Delta\beta_\nu(y,x) - \left\langle \wAd (k_+) \wA(k_-),\; \wj^{\mu}(0) 
\right\rangle_{c,{\rm GE}} \!\!\! \Delta\zeta(y,x) \right) \\
&+& \varrho(k_+) \varrho(-k_-) \theta(k_+^0)\theta(-k_-^0)\frac{1-\e^{\beta(x)\cdot q}}{\beta(x)\cdot q}
\nonumber\\
&\times&\left(\e^{\ii q\cdot\left(x-y\right)} \left\langle \wAd (k_+) \wBd(-k_-),\; \wT^{\mu\nu}(0) 
\right\rangle_{c,{\rm GE}} \!\!\! \Delta\beta_\nu(y,x) - \left\langle \wAd (k_+) \wBd(-k_-),\; \wj^{\mu}(0) 
\right\rangle_{c,{\rm GE}} \!\!\! \Delta\zeta(y,x) +{\rm c.c}\right)\Bigg\}\;,\nonumber
\end{eqnarray}

where we took advantage of the relation:

\begin{equation*}
    \begin{split}
        \left\langle \wAd (k_+) \wBd(-k_-),\; \wT^{\mu\nu}(0) 
\right\rangle^*_{c,{\rm GE}}&=
\e^{-\beta\cdot q}
\, \left\langle \wB (-k_-) \wA(k_+),\; \wT^{\mu\nu}(0) 
\right\rangle_{c,{\rm GE}}\;,\\
\left\langle \wAd (k_+) \wBd(-k_-),\; \wj^{\mu}(0) 
\right\rangle^*_{c,{\rm GE}}&=
\e^{-\beta\cdot q} \, \left\langle \wB (-k_-) \wA(k_+),\; \wj^{\mu}(0) 
\right\rangle_{c,{\rm GE}}\;.
    \end{split}
\end{equation*}

again ensuing from the equations \eqref{abtransl} and \eqref{abtransl2}.

A similar calculation can be carried out for the correlators involving the charged current. The correlator can be 
expanded in terms of the independent vectors $k,\,q$ and $\beta$:

\begin{equation}\label{Y}
        \langle\wAd(k_+)\wA(k_-),\;\wj^\mu(0)\rangle_{c,\rm GE} \equiv Y^\mu\left(k,q,\beta\right)=Y_1(S)\,k^\mu+Y_2(S)\, q^\mu+Y_3(S)\,\beta^\mu\,.
\end{equation}

Again a term proportional to the pseudo-vector $a^\mu$ is forbidden by parity and time-reversal while:

\begin{subequations}\label{Ypar}
    \begin{align}
        Y^\mu\left(k,q,\beta\right)&=\e^{-\beta(x)\cdot q}\theta^\mu_\alpha\, Y^\alpha\left(\widetilde{k},-\widetilde{q},\widetilde{\beta}\right)\,,\\
        Y^\mu\left(k,q,\beta\right)&=\theta^\mu_\alpha\, Y^\alpha\left(\widetilde{k},\widetilde{q},\widetilde{\beta}\right)\,.
    \end{align}
\end{subequations}

Since the charged current is a conserved according to the eq. \eqref{conservation}, for an arbitrary space-like hypersurface 
$\Sigma$ we have a globally conserved charge operator:

\begin{equation}\label{integral current}
    \int_{\Sigma}\di\Sigma_\mu(y)\,\wj^\mu(y)=\wQ\;.
\end{equation}

Hence, integrating over the hyperplane at $t=0$, we obtain: 

\begin{equation*}
    \int_{\Sigma}\di\Sigma_\mu(y)\langle\wAd(k_+)\wA(k_-),\;\wj^\mu(y)\rangle_{c,\rm GE}=\langle\wAd(k_+)\wA(k_-),\;\wQ\rangle_{c,\rm GE}\,,
\end{equation*}

which in turn implies, in view of the form of the density operator \eqref{geq} (see analogous derivation in the
equations \eqref{corrint2}-\eqref{correl1} above):

\begin{equation}\label{Y0}
    \langle\wAd\left(k^0_+,{\bf k}\right)\wA\left(k^0_-,{\bf k}\right),\;\wj^{\,0}(0)\rangle_{c,\rm GE}=\frac{\theta(k^0)}{(2\pi)^2}\frac{1}{\varrho^2(k)}\delta(q^0) \frac{\partial}{\partial\zeta}\left(n_{\rm B}(k)\varrho(k)\right)\,.
\end{equation}

From the conservation of the four-current \eqref{conservation} the Ward identity ensues:

\begin{equation*}
    q_\mu Y^\mu\left(k,q,\beta\right)=0\;,\qquad\forall\,k,\, q,\, \beta\;,
\end{equation*}

implying that the correlator \eqref{Y} can be expanded much the same way as we have seen in eq. \eqref{Theta deltas}:

\begin{equation}\label{Ydeltas}
    Y^\mu\left(k,q,\beta\right)=\sum_{j}\delta\left(s_j-f_j(S)\right)\Upsilon^\mu_{j}\left(k,q,\beta\right)\,,
\end{equation}

where $S$ are all the scalars \eqref{scalars} while $s_j=k\cdot q,\, q\cdot\beta\,,q^2 $. The four-vectors $\Upsilon^\mu_{j}$ 
are assumed to be analytic functions of $q$ so that they are finite and infinitely differentiable in $q=0$.

Again, according to the condition \eqref{Y0}, the only two terms in the expansion \eqref{Ydeltas} which are non-vanishing 
for $q=0$ are those associated with the $q\cdot k=0$ and $q\cdot\beta=0$ delta distributions:

\begin{subequations}\label{Upsilon k e Upsilon beta}
    \begin{align}
        \Upsilon^\mu_k\left(k,q,\beta\right) &=\Upsilon^k_1(S)k^\mu+\Upsilon^k_2(S)
    \left[\left(q\cdot\beta\right) q^\mu-q^2\beta^\mu\right]\;,\\
    \Upsilon^\mu_\beta\left(k,q,\beta\right) &=\Upsilon^\beta_1(S)\beta^\mu+\Upsilon^\beta_2(S)
    \left[\left(q\cdot k\right) q^\mu-q^2k^\mu\right]\;,
    \end{align}
\end{subequations}

whereas all remaining $\Upsilon^\mu_{j}$, along with their first order derivative in $q$ vanish for $q=0$. 
Combining the \eqref{Upsilon k e Upsilon beta} and the \eqref{Y0}, we thus obtain:

\begin{equation}\label{Upsilon 1 in q=0}
 \Upsilon^k_{1}\left(k,q=0,\beta\right)+\Upsilon^{\beta}_1\left(k,q=0,\beta\right) =\frac{\theta(k^0)}{(2\pi)^2\varrho^2(k)}\frac{\partial}{\partial\zeta}\left(n_{\rm B}(k)\varrho(k)\right)\,.
\end{equation}

Note that, in principle, for the four-current terms we are not able to determine separately the two coefficients in $q=0$ like in the case of the stress energy tensor \eqref{Gamma1q0}, but only their sum. However, in the free-limit, $\varrho$ turns out to be independent from $\zeta$ and thus we can conclude that:

\begin{subequations}\label{Upsilonkbeta q0}
    \begin{align}
        \Upsilon^k_1\left(k,0,\beta\right)&=\frac{\theta(k^0)}{(2\pi)^2\varrho(k)}n_{\rm B}(k)\left(1+n_{\rm B}(k)\right)+\Lambda\left(k,\beta\right)\;,\\
        \Upsilon^\beta_1\left(k,0,\beta\right)&=\frac{\theta(k^0)}{(2\pi)^2}n_{\rm B}(k)\frac{\partial\log\varrho}{\partial\zeta}-\Lambda\left(k,\beta\right)\;,
    \end{align}
\end{subequations}

with $\Lambda\left(k,\beta\right)$ scalar function which must be vanishing for free fields so that, for free fields, $\Upsilon^\beta_1\left(k,0,\beta\right)\mapsto0$.

Finally, due to the relations \eqref{Ypar}, using the results from appendix \ref{SECTION: symmetries},   the vectors $\Upsilon_{k/\beta}$ fulfill:

\begin{subequations}\label{Upsiloj q = Upsilon -q exp}
    \begin{align}
        \Upsilon^{\mu}_k\left(k,q,\beta\right)&=\e^{-\beta(x)\cdot q}\,\Upsilon^{\mu}_k\left(k,-q,\beta\right)\,,\\
        \Upsilon^{\mu}_\beta\left(k,q,\beta\right)&=\Upsilon^{\mu}_\beta\left(k,-q,\beta\right)\;,
    \end{align}
\end{subequations}

impying:

\begin{subequations}\label{qderiv Upsilon}
    \begin{align}
        \partial^q_\lambda\,\Upsilon^{\mu}_k\left(k,q,\beta\right)\Big|_{q=0}&=-\frac{1}{2}\beta_\lambda(x)\Upsilon^{\mu}_\beta\left(k,0,\beta\right)\;,\\
        \partial^q_\lambda\,\Upsilon^{\mu}_\beta\left(k,q,\beta\right)\Big|_{q=0}&=-\partial^q_\lambda\,\Upsilon^{\mu}_\beta\left(k,q,\beta\right)\Big|_{q=0}=0\;.
    \end{align}
\end{subequations}

\label{hydrolimit}


We can use the results of the foregoing Section to further develop the off-equilibrium correction of the Wigner
function. With the definition \eqref{thff}, taking into account the vanishing of the correlators involving 
$\wAd\wBd$ and plugging the \eqref{Theta deltas2} into the equation \eqref{deltawig2} a new expression is obtained:

\begin{align}\label{deltawig3}
\Delta W^+(x,k) &=\frac{2}{(2\pi)^5} \sum_{j} \int_{\Sigma_{0}} \di \Sigma_{\mu}(y) 
\int \di^{4}q\;  
\varrho(k_+)\varrho(k_-)\theta(k_+^0)\theta(k_-^0) \e^{\ii q\cdot (x-y)} \frac{1 -\e^{\beta(x)\cdot q}}{\beta(x) \cdot q} \nonumber\\
&\times
 \delta(s_j - f_j(S)) \left[ \Gamma_{j}^{\mu\nu}(k,q,\beta)\Delta\beta_\nu(y,x)-\Upsilon_{j}^\mu(k,q,\beta)\Delta\zeta(y,x) \right]\;.
\end{align}

The standard approach to evaluate this double integral is to introduce a suitable approximation of the integration 
hypersurface \cite{Fu:2021pok,Liu:2021uhn,Becattini:2021suc,Sheng:2024pbw,Zhang:2024mhs} and to integrate first 
in $\di \Sigma_\mu(y)$, assuming that the hydrodynamic fields are slowly varying, so that they can be evaluated
for $y \simeq x$. This method, however, relies on strong geometric assumptions and we recently showed for the local
equilibrium calculation \cite{Sheng:2025cjk} that a much better approximation is obtained by reversing the order of 
integrations, i.e. first integrating in $\di^4 q$, thereafter in $\di \Sigma_\mu(y)$. There is another very good reason 
why the traditional method cannot be adopted: we cannot evaluate the hydrodynamic fields around $y \simeq x$ because $x$ 
lies on $\Sigma_{\rm D}$ and not on $\Sigma_0$, so we cannot expand $\Delta\beta$ and $\Delta\zeta$ around $y=x$. 
Therefore, we deal with the integral \eqref{deltawig3} using a similar way as in our previous work \cite{Sheng:2025cjk}.

The formula \eqref{deltawig3} can be rewritten in a way which makes it apparent the effect of the hydrodynamic limit:

\be\label{deltawig4}
\begin{split}
    \Delta W^+(x,k) =\frac{2}{(2\pi)^5} \sum_{j} \int \di^4 q\;
    \delta (s_j - f_j(S))& \left[ G^{\mu\nu}_{j}\left(k,q,\beta\right) F^{(\beta)}_{\mu\nu}\left(x,q\right)-H_{j}^\mu\left(k,q,\beta\right)F^{(\zeta)}_{\mu}\left(x,q\right)\right]\;, 
\end{split}
\ee

where:

\begin{subequations}\label{Gfunct}
\begin{align}
    &   G_{j}^{\mu\nu}\left(k,q,\beta\right) \equiv \theta(k_+^0)\theta(k_-^0) \frac{1 - \e^{\beta(x)\cdot q}}{\beta(x) \cdot q }
 \varrho(k_+)\varrho(k_-)\Gamma_{j}^{\mu\nu}\left(k,q,\beta\right)\;, \\
&  H_{j}^{\mu}\left(k,q,\beta\right) \equiv \theta(k_+^0)\theta(k_-^0) \frac{1 -\e^{\beta(x)\cdot q}}{\beta(x) \cdot q}
 \varrho(k_+)\varrho(k_-) \Upsilon_{j}^{\mu}\left(k,q,\beta\right)\;,
\end{align}
\end{subequations}

and:

\begin{subequations}\label{Ffunct}
    \begin{align} F^{(\beta)}_{\mu\nu}\left(x,q\right) &= \int_{\Sigma_{0}} \!\!\! \di \Sigma_{\mu}(y) \; 
  \e^{iq\cdot(x-y)} \Delta \beta_\nu(y,x)\;, \\
 F^{(\zeta)}_{\mu}\left(x,q\right) &= \int_{\Sigma_{0}} \!\!\! \di \Sigma_{\mu}(y) \; 
  \e^{\ii q\cdot(x-y)} \Delta\zeta(y,x)\;.
    \end{align}
\end{subequations}

In the hydrodynamic limit, $\Delta\beta_{\nu}$, $\Delta\zeta$ and the normal vector $n_\mu$ to the hypersurface
$\Sigma_0$ are slowly varying functions in space and time, implying that the $F^{(\beta)}_{\mu\nu},\, F^{(\zeta)}_\mu$, which are Fourier 
transform in the variable $q$ integrated in the variable $y$, are functions peaked around $q^{\mu}=0$. This makes 
it possible to obtain a good approximation of the \eqref{deltawig4} by expanding the functions $G^{\mu\nu}_{j}(q)$ 
and $H_{j}^\mu(q)$ around $q^\mu=0$. 

First, we study one of the two cases where the form factors present non-vanishing contributions at the lowest 
order in the $q$ expansion, namely $s=q \cdot k$ and $f_j(S)=0$. This case arose in the calculation of the corrections
to the Wigner function at local equilibrium that we carried it out in detail in ref. \cite{Sheng:2025cjk}. 
Plugging the $q$ expansion in the \eqref{deltawig3} \footnote{The two functions $G_{j}$ and $H_{j}$ feature a $\theta(k^0_+)\theta(k^0_-)$ function which is differentiable for any $k^0 > 0$, being trivially constant equal to 1 
around $q^0=0$; for $k^0=0$ both the functions vanish because $\theta(q^0/2)\theta(-q^0/2) = 0$},
taking into account the definitions of the functions in \eqref{Ffunct} and integrating over $q$, the contribution
to the Wigner function from this term (denoted by $j \to k$) reads:

\begin{equation}\label{deltawiggen}
\begin{split}
    \Delta W_k^+(x,k) &= \frac{2}{(2\pi)^5} \sum_{N=0}^{\infty}\frac{1}{N!}\int_{\Sigma_0} \di \Sigma_{\mu}(y) 
\; I_{N}^{\nu_{1}\nu_{2}\cdots\nu_{N}}(y-x)  \\
& \times \left( \Delta\beta_\nu(y,x) \left[\partial_{\nu_{1}}^{q}\partial_{\nu_{2}}^{q}
\cdots\partial_{\nu_{N}}^{q} G_k^{\mu\nu}\left(k,q,\beta\right)\right]\Big|_{q^{\mu}=0} - \Delta\zeta(y,x) 
\left[\partial_{\nu_{1}}^{q}\partial_{\nu_{2}}^{q}\cdots\partial_{\nu_{N}}^{q}
H_k^{\mu}\left(k,q,\beta\right)\right]\Big|_{q^{\mu}=0} \right)\;,
\end{split}
\end{equation}

where: 

\begin{eqnarray}\label{integrale y-x}
&& I_{N}^{\nu_{1}\nu_{2}\cdots\nu_{N}}(y-x)\equiv\int \di^{4}q\, \delta(q \cdot k)
\e^{-\ii q\cdot(y-x)}q^{\nu_{1}}q^{\nu_{2}}\cdots q^{\nu_{N}} \nonumber \\
=&& (-\ii)^N \partial_x^{\nu_1}\partial_x^{\nu_2}\cdots \partial_x^{\nu_N} 
\int \di^{4}q\,\delta(q\cdot k) \e^{-\ii q\cdot(y-x)} = (2\pi)^3
\frac{(-\ii)^N}{k^0} \partial_x^{\nu_1}\partial_x^{\nu_2}\cdots \partial_x^{\nu_N} \delta^3\left(
\y-\x - \frac{\kb}{k^0} (y^0-x^0) \right)\;,
\end{eqnarray}

keeping in mind that $k^0 > 0$ for the $W^+(x,k)$. The inverse Leibniz formula:

$$
  f g^{(N)} = \sum_{M=0}^N (-1)^M \binom{N}{M} (f^{(M)} g)^{(N-M)}\;,
$$

can be used to isolate the delta function so the \eqref{deltawiggen} becomes:

\begin{eqnarray}\label{deltawig5}
&& \Delta W_k^+(x,k) = \frac{2}{k^0\left(2\pi\right)^2}\sum_{N=0}^{\infty} \frac{(-i)^N}{N!}
\left[\partial^{q}_{\nu_{1}}\cdots\partial^{q}_{\nu_{N}}G^{\mu\nu}\left(k,q,\beta\right)\right]\Big|_{q=0}  
\sum_{M=0}^N \frac{N!(-1)^M}{M!(N-M)!}
 \nonumber \\
&& \times \partial^{\nu_{M+1}}_{x}\cdots\partial^{\nu_{N}}_{x}\int_{\Sigma_{\text{0}}} \di \Sigma_{\mu}(y)
\; \delta^3\left(\y-\x - \frac{\kb}{k^0} (y^0-x^0) \right)\partial^{\nu_{1}}_{x}\ldots\partial^{\nu_{M}}_{x}
\Delta\beta_\nu(y,x) \, +\; {\rm analogous \; term \; for \; 
 \Delta\zeta}\;.
\end{eqnarray}

The key observation is that the presence of the $\delta$--function restricts the support of the integral to those points lying at 
the intersection between the equilibrium hypersurface and:

\begin{equation}\label{worldline}
    {\bf y} = {\bf x} - \frac{\bf k}{k^{0}}(y^0 - x^0)\;,
\end{equation}

corresponding to the world-line of a free particle emitted from $x=(x^0,{\bf x})$ and propagating to $y=(y^0,{\bf y})$ with velocity 
${\bf k}/k^0$. It is important to note, however, that since $k^2 \ne m^2$ the particle is off-mass-shell hence it is a virtual 
particle in the language of Feynman diagrams. Indeed, if $\Sigma_0$ is space-like, at it supposedly is, there is at most one 
intersection between the world-line \eqref{worldline} and the hypersurface, that we will henceforth denote by $\bar y_k(x)$. 
Consequently, one can show (see Appendix~\ref{SECTION: Wigner computation}) that the \eqref{deltawig5} can be transformed into:

\be\label{deltawigk}
\begin{split}
    \Delta W_k^+(x,k) &=\sum_{N=0}^{\infty} \frac{2\theta_k(x)}{\left(2\pi\right)^2}\frac{\left(-\ii \right)^N}{N!} 
\left[D_y(\bar{y}_k(x))\right]^N\\
&\times\left\{ \frac{n_{\mu}(y)}{|k\cdot n(y)|} \left[ G_k^{\mu\nu}\left(k,q,\beta\right) 
\Delta\beta_{\nu}(y,x) - H_k^\mu\left(k,q,\beta\right) \Delta \zeta(y,x) \right] \right\} \Bigg|_{q=0,y=\bar y_k(x)}\;,
\end{split}
\ee

where $\theta_k(x)$ is a Heaviside-like function:

$$
  \theta_k(x) = \begin{cases} 1 \qquad {\rm if \; an \; intersection \; point}\; \bar y_k(x) \; {\rm exists}\;, 
  \\ 0 \qquad {\rm otherwise}\;, \end{cases}
$$

and where we defined:

\begin{equation}\label{Dgrande1}
D_y(\bar y_k(x)) \equiv \Delta^{\nu\rho}(\bar y_k(x))
\partial_{\rho}^{y}\partial_{\nu}^{q}\;,\qquad \Delta^{\nu\rho}(\bar y_k(x))\equiv g^{\nu\rho}-
\frac{n^\nu(\bar{y}_k(x))k^\rho}{\left|k\cdot n(\bar y_k(x))\right|}\; ,
\end{equation}

with $n$ normal vector to the hypersurface  $\Sigma_0$ and $\bar y_k(x)$ intersection between the worldline \eqref{worldline} and $\Sigma_{0}$. 
Note that the operator $\Delta^{\nu\rho}$ is independent on $y$ and therefore in the formula \eqref{deltawigk} the operator 
$D_y$ does not act on itself. The equation \eqref{deltawigk} includes all linear terms in the gradients of $\Delta\beta, \Delta\zeta$ 
to all orders as well as gradients of the normal vector $n$ to the hypersurface; the latter are obviously absent if the hypersurface 
$\Sigma_0$ is a hyperplane. The gradients are evaluated on the initial equilibrium hypersurface $\Sigma_0$, which makes the \eqref{deltawigk}
an expansion of the Wigner function of the kind \eqref{gradexp} discussed in Section \ref{density}. 

A crucial feature of \eqref{deltawigk} is that the order of the gradient of $\beta,\zeta,n$ is $N$, that is the order of the 
expansion in powers of $q$. Therefore, the $q$ expansion of the functions \eqref{Gfunct} corresponds, order by order, to the 
expansion in gradients of this particular contribution to the Wigner function or, otherwise stated, the gradient expansion in 
the thermo-hydrodynamic ($\beta,\zeta$) and geometric ($n$) fields is generated by the expansion in $q$ of the functions 
\eqref{Gfunct}. More specifically, in the \eqref{deltawigk}, the space-time gradients are coupled to derivatives in $q$ of the 
same order for $q=0$, according to the \eqref{Dgrande1}, so the vanishing of a $q$-gradient in $q=0$ implies the vanishing of 
the corresponding term in the space-time gradient expansion. 

The correspondence between the powers of $q$ and the gradients of the fields extends to all other contributions to 
the Wigner function. We now consider the second case where we have non-vanishing terms at the leading order of the 
$q$ expansion of the thermal form factors, namely $s= q \cdot \beta$ and $f_j=0$. In this case, the functions in 
\eqref{Gfunct} can be replaced by:

\begin{subequations}\label{Gfunct2}
    \begin{align}
          G_\beta^{\mu\nu}\left(k,q,\beta\right) &\equiv -\theta(k_+^0)\theta(k_-^0) 
 \varrho(k_+)\varrho(k_-)\Gamma_\beta^{\mu\nu}\left(k,q,\beta\right)\;,  \\
  H_\beta^{\mu}\left(k,q,\beta\right) &\equiv -\theta(k_+^0)\theta(k_-^0) 
 \varrho(k_+)\varrho(k_-) \Upsilon_\beta^{\mu}\left(k,q,\beta\right)\;,
    \end{align}
\end{subequations}

because of the constraint $q \cdot \beta = 0$. The procedure is the same as for the previous $s=q \cdot k$ case,
with the only difference that the equation \eqref{worldline} is replaced by:

\begin{equation}\label{worldline2}
    {\bf y} = {\bf x} - \frac{\betav}{\beta^{0}}(y^0 - x^0)\;,
\end{equation}

which is the world-line of a particle moving with the velocity of the fluid. The resulting contribution to the off-equilibrium correction of the Wigner function are therefore obtained by just replacing $k$ with $\beta$ in the foregoing expressions and 
with the re-definition of the functions $G_\beta$ and $H_\beta$ as in equations \eqref{Gfunct2}:

\be\label{deltawigbeta}
\begin{split}
    \Delta W_\beta^+(x,k) &=\sum_{N=0}^{\infty} \frac{2\theta_\beta(x)}{\left(2\pi\right)^2}\frac{\left(-\ii \right)^N}{N!}\\
    &\times
\left[D_y(\bar{y}_\beta(x))\right]^N \left\{ \frac{n_{\mu}(y)}{|\beta \cdot n(y)|} \left[ G_\beta^{\mu\nu}\left(k,q,\beta\right) 
\Delta\beta_{\nu}(y,x) - H_\beta^\mu\left(k,q,\beta\right) \Delta \zeta(y,x) \right) \right\} \Bigg|_{q=0,y=\bar y_\beta(x)}\;,
\end{split}
\ee

where $\theta_\beta(x)$ is a Heaviside-like function:

$$
  \theta_\beta(x) = \begin{cases} 1 \qquad {\rm if \; an \; intersection \; point}\; \bar y_\beta(x) \; {\rm exists}\;, 
  \\ 0 \qquad {\rm otherwise}\;, \end{cases}
$$

and where we defined:

\begin{equation}\label{Dgrande2}
D_y(\bar y_\beta(x)) \equiv \Delta^{\nu\rho}(\bar y_\beta(x))
\partial_{\rho}^{y}\partial_{\nu}^{q}\;,\qquad \Delta^{\nu\rho}(\bar y_\beta(x))\equiv g^{\nu\rho}-
\frac{n^\nu(\bar{y}_\beta(x))\beta^\rho}{\left|\beta\cdot n(\bar y_\beta(x))\right|}\; .
\end{equation}

The general case can be tackled by first solving the equation $s_j = f_j(S)$ with respect to $q^0$ so 
to turn the delta distribution in \eqref{deltawig3} into:

$$
 \delta(s_j-f_j(S)) = \frac{1}{\chi(\q)}\delta(q^0 - \varphi_j(\q)) \; ;
$$

the arguments $k,\beta$ in the functions $\chi,\varphi$ are understood. In order to fulfill the requirement discussed
in Section \ref{formfactors}, that the delta distributions must reduce to a $\delta(q^0)$ for $\q =0$, the function $\chi(\q)$ must be 
non-vanishing for $\q=0$ whereas $\varphi(\q)$ is ought to vanish for $\q=0$. Hence, the latter can be expanded as:

$$
  \varphi_j(\q) = \nabla_\q \varphi_j|_{\q=0} \cdot \q + R_j(\q) \equiv {\bf v}_j \cdot \q + R_j(\q)\;,
$$

where $R(\q)$ is at least quadratic in the components $q^i$. Therefore, the single contribution $\Delta W^+_{j}$
in eq. \eqref{deltawig3} can be rewritten as:

\begin{align*}
\Delta W_{j}^+(x,k) &=\frac{2}{(2\pi)^5} \int_{\Sigma_{0}} \di \Sigma_{\mu}(y) 
\int \di^{4}q\; \varrho(k_+)\varrho(k_-)\theta(k_+^0)\theta(k_-^0) \e^{\ii q\cdot (x-y)} 
\frac{1 -\e^{\beta(x)\cdot q}}{\beta(x) \cdot q} \nonumber\\
&\times \delta(q^0- {\bf v}_j\cdot \q - R_j(\q))) \frac{1}{\chi(\q)} 
\left[ \Gamma_{j}^{\mu\nu}(k,q,\beta)\Delta\beta_\nu(y,x)-\Upsilon_{j}^\mu(k,q,\beta)\Delta\zeta(y,x) \right]
\nonumber \\
& = \frac{2}{(2\pi)^5} \int_{\Sigma_{0}} \di \Sigma_{\mu}(y) 
\int \di^{3} \qq\; \varrho(k_+)\varrho(k_-)\theta(k_+^0)\theta(k_-^0) \e^{\ii \q \cdot( \y -\x - {\bf v}_j (y^0-x^0))} \e^{-\ii R(\q) (y^0-x^0)} \nonumber\\
& \times \frac{1}{\chi(\q)} \left\{ \frac{1 -\e^{\beta(x)\cdot q}}{\beta(x) \cdot q} \left[ \Gamma_{j}^{\mu\nu}(k,q,\beta)\Delta\beta_\nu(y,x)-\Upsilon_{j}^\mu(k,q,\beta)\Delta\zeta(y,x) \right] \right\}\Bigg|_{q^0={\bf v}_j\cdot \q + R_j(\q)}\;.
\end{align*}

To further proceed, two new vectors can be defined:

$$
q'=q - r = q - (R_j(\q),{\bf 0}) = (q^0-R_j(\q),\q)\;, \qquad \qquad v_j = (1,{\bf v_j})\;.
$$

The vector $r = (R_j(\q),{\bf 0})$ can be seen as a function of either $q$ or $q'$ (since $\q = \q'$) and it has no 
dependence on the time component, i.e. $\partial r/\partial q^0 = \partial r/\partial q'^0 = 0$. $\Delta W^+_j\left(x,k\right)$
can be thus rewritten as:

\begin{align*}
\Delta W_{j}^+(x,k) &= \frac{2}{(2\pi)^5} \int_{\Sigma_{0}} \di \Sigma_{\mu}(y) 
\int \di^4 q\; \delta (q' \cdot v_j) \varrho(k_+)\varrho(k_-)\theta(k_+^0)\theta(k_-^0) \e^{\ii q \cdot (x-y)} 
\nonumber\\
& \times \frac{1}{\chi(\q)} \left\{ \frac{1 -\e^{\beta(x)\cdot q}}{\beta(x) \cdot q} \left[ \Gamma_{j}^{\mu\nu}(k,q,\beta)\Delta\beta_\nu(y,x)-\Upsilon_{j}^\mu(k,q,\beta)\Delta\zeta(y,x) \right] \right\}\;. \nonumber \\
\end{align*}

The integration variable can be changed from $q$ to $q'$ by using the definition above, and the resulting
Jacobian determinant is just 1, so that we can recast the above expression as:

\begin{align*}
\Delta W_{j}^+(x,k) &= \frac{2}{(2\pi)^5} \int_{\Sigma_{0}} \di \Sigma_{\mu}(y) 
\int \di^4 q'\; \, \delta (q' \cdot v_j) \varrho(k_+)\varrho(k_-)\theta(k_+^0)\theta(k_-^0) 
 \e^{\ii q' \cdot (x-y)} \e^{\ii r(q') \cdot (x-y)} \nonumber\\
& \times \frac{1}{\chi(\q')} \left\{ \frac{1 -\e^{\beta(x)\cdot (q'+r(q'))}}{\beta(x) \cdot (q'+r(q'))} 
\left[ \Gamma_{j}^{\mu\nu}(k,q'+r(q'),\beta)\Delta\beta_\nu(y,x)-\Upsilon_{j}^\mu(k,q'+r(q'),\beta)\Delta\zeta(y,x) \right] \right\}\;.
\end{align*}

Then, expanding the exponential $\exp[\ii r(q')\cdot (x-y)]$:

\begin{align*}
\Delta W_{j}^+(x,k) &= \sum_{\ell=0}^\infty \frac{2}{(2\pi)^5} \int_{\Sigma_{0}} \di \Sigma_{\mu}(y) 
\int \di^4 q'\; \, \delta (q' \cdot v_j) \varrho(k_+)\varrho(k_-)\theta(k_+^0)\theta(k_-^0) 
 \e^{\ii q' \cdot (x-y)}(x^0-y^0)^\ell \frac{\ii^\ell R^\ell(\q)}{\ell! \chi(\q')} \nonumber\\
& \times  \left\{ \frac{1 -\e^{\beta(x)\cdot (q'+r(q'))}}{\beta(x) \cdot (q'+r(q'))} 
\left[ \Gamma_{j}^{\mu\nu}(k,q'+r(q'),\beta)\Delta\beta_\nu(y,x)-\Upsilon_{j}^\mu(k,q'+r(q'),\beta)\Delta\zeta(y,x) \right] \right\}\;,
\end{align*}

whence:

\begin{align}\label{deltawigjs3}
\Delta W_{j}^+(x,k) &= \sum_{\ell=0}^\infty \frac{2}{(2\pi)^5} 
\int \di^4 q'\; \, \delta (q' \cdot v_j) \left[ G^{\prime\,\mu\nu}_{j\,(\ell)}\left(k,q',\beta\right) F^{\prime\,(\beta)}_{\mu\nu\,(\ell)}\left(q';x\right)-
H_{j\,(\ell)}^{\prime\,\mu}\left(k,q',\beta\right)F^{\prime\,(\zeta)}_{\mu\nu\,(\ell)}\left(q';x\right) \right]\;. 
\end{align}

Each term of the series can be written in a form which is similar to the two foregoing cases $\Delta W_{k,\beta}^+(x,k)$,
by defining:

\begin{subequations}\label{Gfunctprime}
 \begin{align}
     &  G^{\prime\,\mu\nu}_{j\,(\ell)}\left(k,q',\beta\right)\equiv \varrho(k_+)\varrho(k_-)\theta(k_+^0)\theta(k_-^0) 
 \frac{\ii^\ell R^\ell(\q')}{\chi(\q')}  \frac{1 -\e^{\beta(x)\cdot (q'+r(q'))}}{\beta(x) \cdot (q'+r(q'))} 
 \Gamma_{j}^{\mu\nu}\left(k,q'+r(q'),\beta\right)\;, \\
&  H_{j\,(\ell)}^{\prime\,\mu}\left(k,q',\beta\right) \equiv \varrho(k_+)\varrho(k_-)\theta(k_+^0)\theta(k_-^0) 
 \frac{\ii^\ell R^\ell(\q')}{\chi(\q')} \frac{1 -\e^{\beta(x)\cdot \left(q'+r(q')\right)}}{\beta(x) \cdot (q'+r(q'))} 
  \Upsilon_{j}^\mu(k,q'+r(q'),\beta)\;,
 \end{align}
\end{subequations}

and:

\begin{subequations}\label{Ffunctprime}
\begin{align}
    F^{\prime\,(\beta)}_{\mu\nu\,(\ell)}\left(x,q\right) &= \int_{\Sigma_{0}} \!\!\! \di \Sigma_{\mu}(y) \; 
  \e^{\ii q'\cdot(x-y)} \Delta \beta_\nu(y,x)(x^0-y^0)^\ell\;, \\
 F^{\prime\,(\zeta)}_{\mu\,(\ell)}\left(x,q\right)&= \int_{\Sigma_{0}} \!\!\! \di \Sigma_{\mu}(y) \; 
  \e^{\ii q' \cdot(x-y)} \Delta\zeta(y,x)(x^0-y^0)^\ell \;.
\end{align}
\end{subequations}

The functions in eq. \eqref{Ffunctprime} are strongly peaked around $q'=0$ in the hydrodynamic limit, so those
in \eqref{Gfunctprime} can be expanded around $q'=0$, just like in the previous cases. Because of the distribution 
$\delta(q' \cdot v)$ in the integral \eqref{deltawigjs3}, all the conclusions previously achieved hold. The 
$\Delta W_{j}$ can be written in the form of an expansion, complicated as it may be, of the form \eqref{deltawigk}
and \eqref{deltawigbeta}, where the orders of the $q'$ power expansion correspond to the gradients of the $\beta,\zeta$ 
and $n$ fields evaluated at the intersection point between the hypersurface $\Sigma_0$ and the lines:

$$
   \y = \x - {\bf v}_j(k,\beta) (y^0-x^0)\;,
$$

where we have restored the previously understood dependence of $v_j$ on $k$ and $\beta$. 
For the functions $\Gamma_{j}\left(k,q,\beta\right)$ and $r(q)$ are at least quadratic in $q$, also the functions 
$G'_{j}(q')_{(\ell)}$ and $H'_{j}(q')_{(\ell)}$ turn out to be quadratic in $q'$, implying that there are no contributions 
from the zeroth order and first order gradients in the \eqref{deltawigjs3}.

In conclusion, stopping at the first order of the $q$ expansion amounts to stop at the first order gradient expansion and, 
in this case, the only non-vanishing contributions to the off-equilibrium part of the Wigner function stems from the $\Gamma_k$ 
and $\Gamma_\beta$ form factors. In formulae, the correlators in the equation \eqref{Theta deltas2} read:

$$
 \Theta^{\mu\nu}\left(k,q,\beta\right) = \delta(q \cdot k)\, \Gamma^{\mu\nu}_k\left(k,q,\beta\right) + \delta(q \cdot \beta)\, 
 \Gamma^{\mu\nu}_\beta\left(k,q,\beta\right) + \sum_{j} \delta(s_j - f_j(S)){\cal O}(q^2)\;,
$$

and the off-equilibrium correction, neglecting ${\cal O}(q^2)$ terms, turns out to be:

\begin{align}\label{deltawig1storder}
\Delta W^+(x,k) &\simeq \nonumber \\
& \frac{2}{\left(2\pi\right)^2}\sum_{N=0}^{1} 
\frac{\left(-\ii \right)^N}{N!}\Bigg\{\theta_k(x) 
\left[D_y(\bar{y}_k(x))\right]^N \left\{ \frac{n_{\mu}(y)}{|k\cdot n(y)|} \left[G_k^{\mu\nu}\left(k,q,\beta\right) 
\Delta\beta_{\nu}(y,x) - H_k^\mu\left(k,q,\beta\right) \Delta \zeta(y,x) \right]\right\}\Bigg|_{\substack{q=0 \\y=\bar y_k(x)}} \nonumber \\
&+\theta_\beta(x) 
\left[D_y(\bar{y}_\beta(x))\right]^N \left\{ \frac{n_{\mu}(y)}{|\beta \cdot n(y)|} \left[ G_\beta^{\mu\nu}\left(k,q,\beta\right) 
\Delta\beta_{\nu}(y,x) - H_\beta^\mu\left(k,q,\beta\right) \Delta \zeta(y,x) \right) \right\} \Bigg|_{\substack{q=0 \\y=\bar y_k(x)}} \Bigg\}\;.
\end{align}

It should be stressed, however, that if the hypersurface is curved there are contributions at
the lowest order gradients (zeroth and first order) of the thermo-hydrodynamic fields $\beta$ and $\zeta$ from all $N > 1$ terms, 
obtained by letting derivatives $\partial_y$ in the above corrections \eqref{deltawigk}, \eqref{deltawigbeta} and 
\eqref{deltawigjs3} to act on the field $n^\mu(y)$. Only if the curvature of the hypersurface is small such terms can be 
regarded as small corrections of the main terms with $N=0,1$ \cite{Zhang:2025vlk}. We will henceforth disregard those terms,
keeping in mind though that their potential relevance should be considered for moderately curved hypersurfaces.

Up to the second order in the $q-$derivatives the two functions $G^{\mu\nu}_{k}$ \eqref{Gfunct} and $G^{\mu\nu}_\beta$ 
\eqref{Gfunct2} can be expanded taking into account:

\begin{equation*}
    \begin{split}
        \frac{1-\e^{\beta(x)\cdot q}}{\beta(x)\cdot q}&=-1-\frac{1}{2}\beta_\tau (x)q^\tau-\frac{1}{6}\beta_{\tau_1}(x)
        \beta_{\tau_2}(x)q^{\tau_1}q^{\tau_2}+\mathcal{O}(q^3)\;,\\
        \Gamma^{\mu\nu}_{k/\beta}\left(k,q,\beta\right)&=\Gamma^{\mu\nu}_{k/\beta}\left(k,0,\beta\right)+q^\tau\,
        \frac{\partial}{\partial q^\tau}\Gamma^{\mu\nu}_{k/\beta}\left(k,q,\beta\right)\Bigg|_{q=0}+\frac{1}{2}q^{\tau_1}q^{\tau_2}\,
        \frac{\partial^2}{\partial q^{\tau_1}\partial q^{\tau_2}}\Gamma^{\mu\nu}_{k/\beta}\left(k,q,\beta\right)\Bigg|_{q=0}+\mathcal{O}(q^3)\;,\\
        \varrho(k_+)\varrho(k_-)&=\varrho^2(k)+\frac{1}{8}
        \frac{\partial^2}{\partial q^{\tau_1}\partial q^{\tau_2}}\varrho(k_+)\Bigg|_{q=0}-\frac{1}{4}
        \frac{\partial}{\partial q^{\tau_1}}\varrho(k_+)\Bigg|_{q=0}
        \frac{\partial}{\partial q^{\tau_2}}\varrho(k_-)\Bigg|_{q=0}+\mathcal{O}(q^4)\;,
    \end{split}
\end{equation*}

where $k_\pm=k\pm q/2$.
Similarly we can expand the tensors $\Upsilon^\mu_{k/\beta}$ and the functions $H^\mu_{k/\beta}$ so the functions $G^{\mu\nu}_{k/\beta}$, at lowest  order in $q$, are given by:
\eqref{Gamma1q0}:

\begin{equation*}
    \begin{split}
        G^{\mu\nu}_k\left(k,0,\beta\right)&=-\varrho^2(k)\theta(k^0)\,\Gamma^{\mu\nu}_k\left(k,0,\beta\right)=-\frac{\theta(k^0)}{\left(2\pi\right)^2}\varrho(k)n_{\rm B}(k) \left[ 1+n_{\rm B}(k) 
    - \frac{\partial \log \varrho(k)}{\partial (k \cdot \beta)} \right]k^\mu k^\nu\;,\\
    G^{\mu\nu}_\beta\left(k,0,\beta\right)&=-\varrho^2(k)\theta(k^0)\,\Gamma^{\mu\nu}_\beta\left(k,0,\beta\right)=\frac{2\theta(k^0}{(2\pi)^2} )\varrho(k)n_{\rm B}(k)
  \frac{\partial \log \varrho(k)}{\partial \beta^2}\beta^\mu\beta^\nu\, .
    \end{split}
\end{equation*}

In the same way for the functions $H^\mu_{k/\beta}$ we have:

\begin{equation*}
    \begin{split}
        H^\mu_k\left(k,0,\beta\right)&=-\frac{\theta(k^0)}{(2\pi)^4}\varrho^2(k)\Upsilon^k_1(0)\,k^\mu\;,\\
        H^\mu_\beta\left(k,0,\beta\right)&=-\frac{\theta(k^0)}{(2\pi)^4}\varrho^2(k)\Upsilon^\beta_1(0)\,\beta^\mu\;,
    \end{split}
\end{equation*}

with $\Upsilon^k_1\left(k,0,\beta\right)$ and $\Upsilon^\beta_1\left(k,0,\beta\right)$ given in \eqref{Upsilonkbeta q0}.

Plugging these expressions in \eqref{deltawig1storder} and taking the $N=0$ term we then obtain the off-equilibrium 
correction to the Wigner function at the leading order of the gradient expansion which reads:

\begin{align}\label{zerorder}
\Delta^{(0)}W\left(x,k\right)&=\frac{2\varrho(k)n_{\rm B}(k)}{(2\pi)^4}\Bigg\{
{\theta_k(x)}\left(1+n_{\rm B}(k)-\frac{\partial\log\varrho(k)}{\partial(k \cdot \beta)} \right)\Big[k\cdot\beta(x)-k\cdot\beta\left(\overline{y}_k(x)\right)\Big] \nonumber\\
&\qquad\qquad\qquad\quad-2\theta_\beta(x) \frac{\partial\log\varrho(k)}{\partial\beta^2}\Big[\beta^2(x)-\beta(x)\cdot \beta(\overline{y}_\beta(x))\Big]\Bigg\} \\
&+\frac{2\varrho^2(k)}{(2\pi)^2}\Bigg\{\theta_k(x)\Upsilon^k_1\left(k,0,\beta\right)\left[\zeta(\overline{y}_k(x))-\zeta(x)\right]+\theta_\beta(x)\Upsilon^\beta_1\left(k,0,\beta\right)\left[\zeta(\overline{y}_\beta(x))-\zeta(x)\right]\Bigg\}\,.\nonumber
\end{align}

At the first order in the gradient expansion the correction is given by the $N=1$ term in \eqref{deltawig1storder}:

\begin{align*}
\Delta^{(1)} W^+(x,k) &= -\frac{\ii\theta_k(x)}{(2\pi)^2}\Big\{ 
\partial^q_\sigma G^{\mu\nu}_k\left(k,q,\beta\right)\Big|_{q=0}\Delta^{\sigma\gamma}(\bar{y}_k(x))\partial^y_\gamma 
\left[ \frac{n_{\mu}(y)\Delta\beta_{\nu}(y,x)}{|k\cdot n(y)|} \right] \Bigg|_{y=\bar y_k(x)}\nonumber\\
&-\partial^q_\sigma H^{\mu}_k\left(k,q,\beta\right)\Big|_{q=0}\Delta^{\sigma\gamma}(\bar{y}_k(x))\partial^y_\gamma 
\left[ \frac{n_{\mu}(y)\Delta\zeta(y,x)}{|k\cdot n(y)|} \right] \Bigg|_{y=\bar y_k(x)}\Big\} \nonumber \\
& -\frac{\ii\theta_\beta(x)}{\left(2\pi\right)^2}
\Big\{ \partial^q_\sigma G^{\mu\nu}_\beta\left(k,q,\beta\right)\Big|_{q=0}\Delta^{\sigma\gamma}(\bar{y}_\beta(x)\partial^y_\gamma 
\left[ \frac{n_{\mu}(y)\Delta\beta_{\nu}(y,x)}{|k\cdot n(y)|} \right] \Bigg|_{y=\bar y_\beta(x)}\nonumber\\
&-\partial^q_\sigma H^{\mu}_\beta\left(k,q,\beta\right)\Big|_{q=0}\Delta^{\sigma\gamma}(\bar{y}_\beta(x))\partial^y_\gamma 
\left[ \frac{n_{\mu}(y)\Delta\zeta(y,x)}{|k\cdot n(y)|} \right] \Bigg|_{y=\bar y_\beta(x)}\Big\}\;.
\end{align*}

This contribution exactly vanishes. This can be shown by calculating the first order derivative with respect to $q$, 
of the functions $G^{\mu\nu}_{k/q}$ and $H^\mu_{k/q}$. For the $q\cdot k=0$ channel one has:

\begin{equation*}
    \begin{split}
        \partial^q_\lambda G^{\mu\nu}_k\left(k,q,\beta\right)\Big|_{q=0}&=\varrho^2(k)\left[-\frac{1}{2}\beta_\lambda(x) 
        \Gamma^{\mu\nu}_k\left(k,0,\beta\right)+\partial^q_\lambda\Gamma^{\mu\nu}_k\left(k,q,\beta\right)\Big|_{q=0}\right]=0\,,\\
        \partial^q_\lambda H^{\mu\nu}_k\left(k,q,\beta\right)\Big|_{q=0}&=\varrho^2(k)\left[-\frac{1}{2}\beta_\lambda(x) 
        H^{\mu\nu}_k\left(k,0,\beta\right)+\partial^q_\lambda H^{\mu\nu}_k\left(k,q,\beta\right)\Big|_{q=0}\right]=0\,,
    \end{split}
\end{equation*}

while for the $q\cdot\beta=0$ channel one has:

\begin{equation*}
    \begin{split}
        \partial^q_\lambda G^{\mu\nu}_k\left(k,q,\beta\right)\Big|_{q=0}&=\varrho^2(k)\,\partial^q_\lambda\Gamma^{\mu\nu}_k\left(k,q,\beta\right)\Big|_{q=0}=0\,,\\
        \partial^q_\lambda H^{\mu\nu}_k\left(k,q,\beta\right)\Big|_{q=0}&=\varrho^2(k)\,\partial^q_\lambda H^{\mu\nu}_k\left(k,q,\beta\right)\Big|_{q=0}=0\,,
    \end{split}
\end{equation*}

where both vanish due to the relations \eqref{Gamma q = Gamma -q exp} and \eqref{Upsiloj q = Upsilon -q exp}. Hence:

\begin{equation*}
    \Delta^{(1)}W\left(x,k\right)=0\;.
\end{equation*}

Altogether, the off-equilibrium correction of the Wigner function can be written as:

\begin{equation}
    \Delta W^+\left(x,k\right)=\Delta^{(0)}W\left(x,k\right)+\mathcal{O}(\partial^2)\;.
\end{equation}

The higher order corrections in the above equation are far more complicated than the the leading term 
\eqref{zerorder} and will depend on all the form factors and on the all possible delta channels $\delta(s_j -f_j(S))$
in the equation \eqref{deltawig4}.

\label{SECTION: aa is not independent}


We show that the tensor $a^{\mu}a^{\nu}$, where $a^{\mu}\equiv\epsilon^{\mu\rho\sigma\tau}k_{\rho}q_{\sigma}\beta_{\tau}$, 
can be expressed in terms of other symmetric tensors built with $k,q$ and $\beta$. To make notation compact, we introduce 
the four-vectors $\bar{q}^{\mu}$and $\bar{\beta}^{\mu}$ such that $k^{\mu},\bar{q}^{\mu},\bar{\beta}^{\mu}$ are perpendicular 
to each other:
as:

\begin{eqnarray}\label{qbetabar}
\bar{q}^{\mu} & = & \left(g^{\mu\nu}-\frac{k^{\mu}k^{\nu}}{k\cdot k}\right)q_{\nu}\nonumber\;, \nonumber \\
\bar{\beta}^{\mu} & = & \left(g^{\mu\nu}-\frac{\bar{q}^{\mu}\bar{q}^{\nu}}{\bar{q}\cdot\bar{q}}\right)
\left(g_{\nu\rho}-\frac{k_{\nu}k_{\rho}}{k\cdot k}\right)\beta^{\rho}\;.
\end{eqnarray}

Thereby $a^{\mu}$ can be written as:

\begin{equation*}
a^{\mu}=\epsilon^{\mu\rho\sigma\tau}k_{\rho}\bar{q}_{\sigma}\bar{\beta}_{\tau}\; ;
\end{equation*}

thus:

\be\label{amu1}
a^{\mu}a^{\nu} = \epsilon^{\mu\rho\sigma\tau}k_{\rho}\bar{q}_{\sigma}\bar{\beta}_{\tau}
\epsilon^{\nu\alpha\lambda\xi}k_{\alpha}\bar{q}_{\lambda}\bar{\beta}_{\xi} = 
\epsilon^{\mu\rho\sigma\tau}k_{\rho}\tilde{q}_{\sigma}\bar{\beta}_{\tau}
\epsilon_{\ \alpha}^{\nu\ \lambda\xi}k^{\alpha}\bar{q}_{\lambda}\bar{\beta}_{\xi}\;.
\ee

With the help of the Schouten identity, we can write:

\begin{equation*}
\epsilon^{\mu\rho\sigma\tau}k^{\alpha}=-\left(\epsilon^{\rho\sigma\tau\alpha}k^{\mu}+
\epsilon^{\sigma\tau\alpha\mu}k^{\rho}+
\epsilon^{\tau\alpha\mu\rho}k^{\sigma}+\epsilon^{\alpha\mu\rho\sigma}k^{\tau}\right)\;,
\end{equation*}

hence the \eqref{amu1} can be rewritten as:

\begin{equation*}
a^{\mu}a^{\nu}=-\left(\epsilon^{\rho\sigma\tau\alpha}k^{\mu}+\epsilon^{\sigma\tau\alpha\mu}k^{\rho}+
\epsilon^{\tau\alpha\mu\rho}k^{\sigma}+\epsilon^{\alpha\mu\rho\sigma}k^{\tau}\right)
\epsilon_{\ \alpha}^{\nu\ \lambda\xi}k_{\rho}\bar{q}_{\sigma}\bar{\beta}_{\tau}\bar{q}_{\lambda}\bar{\beta}_{\xi}\;.
\end{equation*}

The contraction of two Levi-Civita symbols in the above equation can be expanded as:

\begin{eqnarray*}
\epsilon^{\rho\sigma\tau\alpha}\epsilon_{\ \alpha}^{\nu\ \lambda\xi} & = & 
\epsilon^{\alpha\rho\sigma\tau}\epsilon_{\alpha}^{\ \nu\lambda\xi}\nonumber \\
 & = & -g^{\rho\nu}(g^{\sigma\lambda}g^{\tau\xi}-g^{\sigma\xi}g^{\tau\lambda})
 -g^{\rho\lambda}(g^{\sigma\xi}g^{\tau\nu}-g^{\sigma\nu}g^{\tau\xi}) -g^{\rho\xi}
 (g^{\sigma\nu}g^{\tau\lambda}-g^{\sigma\lambda}g^{\tau\nu})\;.
\end{eqnarray*}

Since $k\cdot\bar{q}=k\cdot\bar{\beta}=\bar{q}\cdot\bar{\beta}=0$, the \eqref{amu1} can be finally cast
in the following form:

\begin{eqnarray*}
a^{\mu}a^{\nu} & = & -\left(\epsilon^{\alpha\rho\sigma\tau}\epsilon_{\alpha}^{\ \nu\lambda\xi}k^{\mu}
-\epsilon^{\alpha\sigma\tau\mu}\epsilon_{\alpha}^{\ \nu\lambda\xi}k^{\rho}+\epsilon^{\alpha\tau\mu\rho}
\epsilon_{\alpha}^{\ \nu\lambda\xi}k^{\sigma}-\epsilon^{\alpha\mu\rho\sigma}
\epsilon_{\alpha}^{ \nu\lambda\xi}k^{\tau}\right)k_{\rho}\bar{q}_{\sigma}\bar{\beta}_{\tau}\bar{q}_{\lambda}
\bar{\beta}_{\xi}\nonumber \\
 & = & \bar{q}^{2}\bar{\beta}^{2}k^{\mu}k^{\nu}+k^{2}\bar{\beta}^{2}\bar{q}^{\mu}\bar{q}^{\nu}+
 k^{2}\bar{q}^{2}\bar{\beta}^{\mu}\bar{\beta}^{\nu}-k^{2}\bar{q}^{2}\bar{\beta}^{2}g^{\mu\nu}\;.
\end{eqnarray*}

Since $\bar{q}^{\mu}$ and $\bar{\beta}^{\mu}$ are defined as linear combinations of $k^{\mu}$, $q^{\mu}$, and $\beta^{\mu}$
in equation \eqref{qbetabar}, we can further expand $\bar{q}^{\mu}\bar{q}^{\nu}$ and $\bar{\beta}^{\mu}\bar{\beta}^{\nu}$
in terms of $k^{\mu}k^{\nu}$, $q^{\mu}q^{\nu}$, $\beta^{\mu}\beta^{\nu}$, $k^{\mu}q^{\nu}+k^{\nu}q^{\mu}$, 
$k^{\mu}\beta^{\nu}+k^{\nu}\beta^{\mu}$ and $q^{\mu}\beta^{\nu}+q^{\nu}\beta^{\mu}$. As a consequence, $a^{\mu}a^{\nu}$
turns out to be a linear combination of these symmetric tensors and $g^{\mu\nu}$.

\label{SECTION: symmetries}


The correlators in the equation \eqref{thff} are constrained by the properties of the density operator, creation/annihilation operators and stress-energy tensor operator under discrete transformations: complex conjugation, 
time-reversal and parity. The correlator is defined as:

\begin{equation}\label{App: Definizione Exp Val}
 \begin{split}
     \langle\wAd(k_+)\wA(k_-),\wT^{\mu\nu}(0)\rangle_{c,\mathrm{GE}}  &=\frac{1}{Z}\Tr\left(\e^{-\beta(x)\cdot\wP+\zeta(x)\wQ}\wAd(k_+)\wA(k_-)\wT^{\mu\nu}(0)\right)\\
 &-
\frac{1}{Z}\Tr\left(\e^{-\beta(x)\cdot\wP+\zeta(x)\wQ}\wAd(k_+)\wA(k_-)\right) 
\frac{1}{Z}\Tr\left(\e^{-\beta(x)\cdot\wP+\zeta(x)\wQ}\,\wT^{\mu\nu}(0)\right)\;.
 \end{split}
\end{equation}

Taking the complex conjugate of both sides, using $\Tr(\wO)^*=\Tr(\wO^\dagger)$ and the relations \eqref{abtransl}, \eqref{abtransl2}
one obtains:

\begin{equation*}
 \langle\wAd(k_+)\wA(k_-),\wT^{\mu\nu}(0)\rangle_{c,\mathrm{GE}}^* = 
 \langle\wAd(k_-)\wA(k_+),\wT^{\mu\nu}(0)\rangle_{c,\mathrm{GE}} \, \e^{-\beta(x) \cdot q}
\end{equation*}

where $q=k_+-k_-$. Hence, according to the definition \eqref{thff}:

\begin{equation}\label{app parity:ThetaKMS}
    \Theta^{\mu\nu}\left(k,q,\beta\right)^*=\e^{-\beta(x)\cdot q}\,\Theta^{\mu\nu}\left(k,-q,\beta\right)\;.
\end{equation}

We now come to the time-reversal and parity transformations. At operator level time-reversal and parity are described by an 
involutive anti-unitary $\wmT$ and a unitary operator $\wPi$ respectively:

\begin{subequations}\label{App1: TR operator}
    \begin{align}
        \wmT^{\dagger}&=\wmT^{-1},\quad\wmT^2=\mathrm{I},\quad \wmT\left(\alpha\left|\mathcal{H}\right.\rangle\right)=\alpha^*\wmT\left|\mathcal{H}\right.\rangle\;,\\
        \wPi^\dagger&=\wPi^{-1},\quad \wPi^2=\mathrm{I},\quad \wPi\left(\alpha\left|\mathcal{H}\right.\rangle\right)=\alpha\wPi\left|\mathcal{H}\right.\rangle\;,
    \end{align}
\end{subequations}

with $\left|\mathcal{H}\right.\rangle$ is a complex vector on an Hilbert space and $\alpha\in\mathbb{C}$ is a complex 
number.
The field transforms under time-reversal and parity as follows:

$$
  \wmT \wphi(x) \wmT = \eta_T \wphi(-x^0,\x) \qquad \wPi \wphi(x) \wPi = \eta_\Pi \wphi(x^0,-\x)
$$

where $\eta_T$ and $\eta_\Pi$ are phase factors $= \pm 1$. Hence, from \eqref{intfield}, it follows:

\begin{subequations}
    \begin{align}
        \wmT\,\widehat{A}(k)\,\wmT&=\eta_{T}\widehat{A}(\widetilde{k}),\;\qquad\wmT\,\widehat{A}^\dagger(k)\,\wmT=\eta^*_T\widehat{A}^\dagger(\widetilde{k})\;,\\
        \wPi\,\widehat{A}(k)\,\wPi&=\eta_{\Pi}\widehat{A}(\widetilde{k}),\;\qquad\wPi\,\widehat{A}^\dagger(k)\,\wPi=\eta^*_\Pi\widehat{A}^\dagger(\widetilde{k})\;,
    \end{align}
\end{subequations}

where $\widetilde{k}$ is the time-reversal/parity transformed of the four-momentum $k$:

\begin{equation}\label{tr k}
    k=\left(k^0,{\bf k}\right)\mapsto\widetilde{k}=\left(k^0,-{\bf k}\right)\;.
\end{equation}

The stress-energy tensor operator in $x=0$ transforms under time reversal as:

$$
   \wmT \wT^{\mu\nu}(0) \wmT = \theta^{\mu}_\alpha \theta^\nu_\beta \wT^{\alpha\beta}(0) 
$$

and likewise for parity, with $\theta^\mu_\alpha=\text{diag}\left(1,-1,-1,-1\right)$. In turn, the density
operator at global equilibrium is such that:

\begin{equation}\label{trhot}
    \wmT \wrho_{\rm GE}(\beta,\zeta) \wmT = \wrho_{\rm GE}(\widetilde \beta,\zeta) 
\end{equation}

and likewise for parity, where $\widetilde\beta$ is defined the same way as $\widetilde k$ in eq. \eqref{tr k}. 
From the \eqref{trhot} and the general relation:

$$
  \Tr (\wO^\dagger) = \Tr (\wO)^* = \Tr (\wmT \wO \wmT) 
$$

with $\wO$ any operator, the following relation can be obtained for the correlator in eq. \eqref{thff}:

\begin{equation}\label{App1: TR relation per Gamma finale}
    \Theta^{\mu\nu}\left(k,q,\beta\right)=\e^{-\beta(x)\cdot q}\theta^\mu_\alpha\theta^\nu_\beta 
    \:\Theta^{\alpha\beta}\left(\widetilde{k},-\widetilde{q},\tilde{\beta}\right)\;.
\end{equation}

Likewise, for parity, being $\wPi$ linear, one has:

$$
  \Tr (\wO) = \Tr (\wPi\, \wO\, \wPi)\;, 
$$

and correspondingly:

\begin{equation}\label{App1: Parity relation per Gamma finale}
\Theta^{\mu\nu}\left(k,q,\beta\right)=\theta^\mu_\alpha\theta^\nu_\beta\;
\Theta^{\alpha\beta}\left(\widetilde{k},\widetilde{q},\widetilde{\beta}\right)\;.
\end{equation}

The extension of the relations~\eqref{app parity:ThetaKMS}, \eqref{App1: TR relation per Gamma finale}, 
and \eqref{App1: Parity relation per Gamma finale} to the tensor coefficients $\Gamma^{\mu\nu}_j$ appearing 
in Eq.~\eqref{Theta deltas2} is not straightforward. The scalar arguments $S$ defined in Eq.~\eqref{scalars} 
are invariant under the replacement of all four-vectors by their tilde-transformed counterparts, corresponding 
to parity or time-reversal transformations. However, they are not, in general, invariant under the transformation 
$q \mapsto -q$. As a consequence, while the constraints imposed by a $\delta$ function and by the same $\delta$ 
function with tilde-transformed arguments coincide, this is not generally the case when the sign of $q$ is 
also sign-reversed.

For the parity transformations, the invariance of arguments of the $\delta$ functions allows one to extend the 
relation~\eqref{App1: Parity relation per Gamma finale} to each tensor $\Gamma^{\mu\nu}_j$ independently, yielding:

\begin{equation*}
    \Gamma^{\mu\nu}_{j}\left(k,q,\beta\right) =
    \theta^\mu_{\alpha}\,\theta^\nu_{\beta}\;
    \Gamma^{\alpha\beta}_{j}\left(\widetilde{k},\widetilde{q},\widetilde{\beta}\right)\, .
\end{equation*}

On the other hand, upon plugging the expansion~\eqref{Theta deltas2} into the relations~\eqref{app parity:ThetaKMS} and 
\eqref{App1: TR relation per Gamma finale}, it is found that the transformation $q \mapsto -q$ changes, in general, the argument of the delta distribution, mapping the tensor $\Gamma_j$ into a different term. In symbols:

\begin{equation*}
    \begin{split}
        \Gamma^{\mu\nu}_j\left(k,q,\beta\right)
        &= \e^{-\beta(x)\cdot q}\,
        \Gamma^{\mu\nu}_{\underline{j}}\left(k,-q,\beta\right)\, , \\
        \Gamma^{\mu\nu}_j\left(k,q,\beta\right)
        &= \e^{-\beta(x)\cdot q}\,
        \theta^\mu_{\alpha}\,\theta^\nu_{\beta}\,
        \Gamma^{\alpha\beta}_{\underline{j}}\left(\widetilde{k},-\widetilde{q},\widetilde{\beta}\right)\, .
    \end{split}
\end{equation*}

where $\Gamma_{\underline{j}}$ denotes the tensor in the expansion~\eqref{Theta deltas2} associated with the $\delta$ function fulfilling:

\begin{equation*}
    \delta\!\left(s_{\underline{j}} - f_{\underline{j}}(S)\right)\Big|_{q \mapsto -q}
    =\delta\!\left(s_j - f_j(S)\right)\, .
\end{equation*}

For the two specific cases $s = q \cdot k$ and $s = q \cdot \beta$, with $f_j(S) = 0$, denoted by $j = k$ and $j = \beta$ respectively, 
the transformation $q \mapsto -q$ leaves the $\delta$-constraint unchanged. Thus we get:

\begin{subequations}\label{app: Gamma relations k}
    \begin{align}
        \Gamma^{\mu\nu}_{k}\left(k,q,\beta\right)^*
        &= \e^{-\beta(x)\cdot q}\,
        \Gamma^{\mu\nu}_{k}\left(k,-q,\beta\right)\, , \\
        \Gamma^{\mu\nu}_{k}\left(k,q,\beta\right)
        &= \e^{-\beta(x)\cdot q}\,
        \theta^\mu_{\alpha}\,\theta^\nu_{\beta}\,
        \Gamma^{\alpha\beta}_{k}\left(\widetilde{k},-\widetilde{q},\widetilde{\beta}\right)\, , \\
        \Gamma^{\mu\nu}_{k}\left(k,q,\beta\right)
        &= \theta^\mu_{\alpha}\,\theta^\nu_{\beta}\,
        \Gamma^{\alpha\beta}_{k}\left(\widetilde{k},\widetilde{q},\widetilde{\beta}\right)\, .
    \end{align}
\end{subequations}

Similarly, for the case $j = \beta$, one finds:

\begin{subequations}\label{app: Gamma relations beta}
    \begin{align}
        \Gamma^{\mu\nu}_{\beta}\left(k,q,\beta\right)^*
        &= \Gamma^{\mu\nu}_{\beta}\left(k,-q,\beta\right)\, , \\
        \Gamma^{\mu\nu}_{\beta}\left(k,q,\beta\right)
        &= \theta^\mu_{\alpha}\,\theta^\nu_{\beta}\,
        \Gamma^{\alpha\beta}_{\beta}\left(\widetilde{k},-\widetilde{q},\widetilde{\beta}\right)\, , \\
        \Gamma^{\mu\nu}_{\beta}\left(k,q,\beta\right)
        &= \theta^\mu_{\alpha}\,\theta^\nu_{\beta}\,
        \Gamma^{\alpha\beta}_{\beta}\left(\widetilde{k},\widetilde{q},\widetilde{\beta}\right)\, .
    \end{align}
\end{subequations}


Finally, since the four-current operator $\widehat{j}^\mu(0)$ is Hermitian and transforms under parity and time 
reversal as:

\begin{equation*}
    \widehat{j}^\mu(0) \mapsto \theta^\mu_{\alpha}\,\widehat{j}^\alpha(0)\, ,
\end{equation*}

the relations~\eqref{app parity:ThetaKMS}, \eqref{App1: TR relation per Gamma finale}, and \eqref{App1: Parity relation per Gamma finale} can be straightforwardly extended to the current expectation values, yielding

\begin{subequations}\label{app: relations Upsilon*}
    \begin{align}
        Y^\mu\left(k,q,\beta\right)^*
        &= \e^{-\beta(x)\cdot q}\,
        Y^\mu\left(k,-q,\beta\right)\, , \\
        Y^\mu\left(k,q,\beta\right)
        &= \e^{-\beta(x)\cdot q}\,
        \theta^\mu_{\alpha}\,
        Y^\alpha\left(\widetilde{k},-\widetilde{q},\widetilde{\beta}\right)\, , \\
        Y^\mu\left(k,q,\beta\right)
        &= \theta^\mu_{\alpha}\,
        Y^\alpha\left(\widetilde{k},\widetilde{q},\widetilde{\beta}\right)\, .
    \end{align}
\end{subequations}

\label{SECTION: Wigner computation}


The calculation of the correction to the Wigner function for the branches proportional to $\delta(q\cdot k)$ and $\delta(q \cdot \beta)$ 
in the equation \eqref{deltawig3} essentially proceeds through the same steps of the calculation in ref. \cite{Sheng:2025cjk}, the 
main difference being that the integration is done over the initial equilibrium hypersurface and not the decoupling one. We show the 
full calculation for the branch proportional to $\delta(q\cdot k)$, the computation for the branch proportional to $\delta(q\cdot\beta)$ 
being very similar.

We start from the equation \eqref{deltawig5} and we assume the hypersurface $\Sigma_0$ to be space-like and future-oriented 
and parametrized as a single function $y^0 = f({\bf y})$ in Cartesian coordinates. This simplifies the derivation, which can be 
anyhow extended to more complicated topologies \cite{Sheng:2025cjk}. The vector perpendicular to the hypersurface and future-oriented 
is the four-gradient of $(y^0 - f({\bf y}))$:

\begin{equation*}
\sigma_{\mu}(y)=\left(1,-\frac{\partial f}{\partial{\bf y}}\right)\;.
\end{equation*}

Denoting:

$$
 \Theta(y,x) = \partial^{\nu_{1}}_{x}\cdots\partial^{\nu_{M}}_{x} \Delta\beta_{\nu}(y,x)\;,
 \qquad {\rm or} \qquad \Theta(y,x) = \partial^{\nu_{1}}_{x}\cdots\partial^{\nu_{M}}_{x} \Delta\zeta(y,x)\;,
$$

the integral in \eqref{deltawig5} gives rise to:

\begin{eqnarray}\label{deltas}
&& \int_{\Sigma_0} \di \Sigma_{\mu}(y) \; \delta^{3}\left({\bf y}-{\bf x}-\frac{\bf k}{k^{0}}
(y^{0}-x^{0})\right) \Theta(y,x) = \int_{\Sigma_0} \di^3 {\rm y} \; \sigma_{\mu}(y)\;  
\delta^{3}\left({\bf y}-{\bf x}-\frac{\bf k}{k^{0}}(y^{0}-x^{0})\right) \Theta(y,x) \nonumber \\
&& = \sum_{i} \int_{\Sigma_0} \di^3 {\rm y} \; \sigma_{\mu}(y)\; \frac{|k^0|}{|k\cdot\sigma(y)|}
\delta^{3}({\bf y}-\bar{\bf y}_{i}) \Theta(y,x) = \sum_{i} \sigma_{\mu}(\bar y_{i})\; \frac{|k^0|}{|k\cdot\sigma(\bar y_{i})|} \Theta(\bar y_{i}(x),x)\;,
\end{eqnarray} 

where $\bar{\bf y}_{i}$ is the $i$-th solution of the equation ${\bf y} = {\bf x}-({\bf k}/k^0)(f({\bf y})-
x^{0})$, yielding the intersection of the hypersurface $\Sigma_0$ with the world-line of an off-mass-shell particle moving 
with velocity ${\bf k}/k^0$:

\begin{equation*}
    {\bf y} = {\bf x}-\frac{\bf k}{k^{0}}(y^0-x^0)\;,
\end{equation*}

and it is obviously a function of $x$ and $k$. Indeed, if $\Sigma_0$ is space-like, at it supposedly is, there is at 
most one intersection, denoted by $\bar y_k(x)$. Note that in the equation \eqref{deltas} the pre-factor $k^0/ k\cdot \sigma$ 
is the inverse of the determinant of the matrix:

$$
\frac{\partial}{\partial y^j}\left[{\bf y}-{\bf x}- \frac{\bf k}{k^0}(f({\bf y})-x^{0})\right]^i =
\delta^i_j - \frac{k^i}{k^0} \frac{\partial f({\bf y})}{\partial y^j} = \delta^i_j - \frac{k^i}{k^0} 
\sigma^j \;. 
$$

Using the relations \eqref{deltas}, and replacing $\sigma$ with the unit vector normal to the hypersurface:

$$
  n_\mu = \frac{\sigma_\mu}{\sqrt{|\sigma \cdot \sigma|}}\;,
$$

the equation \eqref{deltawig5} is converted to:

\begin{eqnarray}\label{deltawig-y}
\Delta W^{+}(x,k) & = & \frac{2}{k^0\left(2\pi\right)^2}\sum_{N=0}^{\infty}\frac{(-1)^{N}}{N!}
\left.\left[\partial^{q}_{\nu_{1}}\ldots\partial^{q}_{\nu_{N}}G^{\mu\nu}_k(q)\right]\right|_{q=0}
 \sum_{M=0}^{N}\frac{N!(-1)^{M}}{M!(N-M)!} \nonumber \\
 && \times \di^{\nu_{M+1}}_{x}\ldots\di^{\nu_{N}}_{x}
 \left[\left.\frac{n_{\mu}}{|k\cdot n|}\partial^{\nu_{1}}_{x}\ldots\partial^{\nu_{M}}_{x}
 \Delta\beta_{\nu}(y,x)\right] \right|_{y=\bar{y}(x,k)} +\; {\rm analogous \; term \; for \; ,
 \Delta\zeta}
\end{eqnarray}


where we have introduced the total derivative:

$$
\di^\mu_x = \frac{\di}{\di x^\mu}\;,
$$

to emphasize the difference between the derivative acting on the function {\em before} setting 
$y=\bar y_k(x)$ (that is $\partial_x$) and the derivative acting on the function {\em after}
setting $y=\bar y_k(x)$. 
Now, the derivative of the function $y^\nu = \bar y_{k}^\nu(x)$ is obtained by taking into account
that:

\begin{equation*}
\bar{{\bf y}}_{k}-\frac{{\bf k}}{k^{0}}\bar{y}_{k}^{0}={\bf x}-\frac{{\bf k}}{k^{0}}x^{0}\;,
\end{equation*}

with $\bar{y}_{k}^{0} =f_{k}(\bar{{\bf y}}_{k})$. Taking partial derivatives with respect to $x^\mu$
of the above equation:

\begin{equation*}
\frac{\partial\bar{y}_{k}^{j}}{\partial x^{\mu}}-\frac{k^{j}}{k^{0}}\frac{\partial\bar{y}_{k}^{0}}
{\partial\bar{y}_{k}^{l}}\frac{\partial\bar{y}_{k,i}^{l}}{\partial x^{\mu}} = 
\left[ \delta^j_l + \frac{k^j}{k^0} \sigma_l \right] \frac{\partial\bar{y}_{k}^{l}}{\partial x^{\mu}} 
= \delta_{\mu}^{j}-\frac{k^{j}}{k^{0}}\delta_{\mu}^{0}\;,
\end{equation*}

where $j,l=1,2,3$ and where $\sigma_{\mu}(\bar{y}_{k})$ is the normal vector of $\Sigma_{\rm D}$ at 
the spacetime point $\bar{y}_{k}$,

\begin{equation*}
\sigma_{\mu}(\bar{y}_{k})=\left(1,-\frac{\partial f_{k}(\bar{{\bf y}}_{k})}
{\partial\bar{{\bf y}}_{k}}\right)\;.
\end{equation*}

The $3 \times 3$ matrix:

$$
  A^j_l = \left[ \delta^j_l + \frac{k^j}{k^0} \sigma_l \right]\;,
$$

can be inverted and one obtains:

\be\label{deriv1}
\frac{\partial\bar{y}_{k,i}^{j}}{\partial x^{\mu}} = \left(A^{-1}\right)^{j}_{\;\; l} \left(\delta_{\mu}^{l}-
\frac{k^{l}}{k^{0}}\delta_{\mu}^{0}\right) = \left( \delta^j_l - \frac{k^j \sigma_l}{k \cdot \sigma} \right)  
\left(\delta_{\mu}^{l}-\frac{k^{l}}{k^{0}}g_{\mu}^{0}\right)\;.
\ee

Similarly, one can calculate the derivative of $y^0$ with respect to $x$:

$$
\frac{\partial\bar{y}_{k}^{0}}{\partial x^{\mu}} = \frac{\partial\bar{y}_{k}^{0}}
{\partial\bar{y}_{k}^{j}}\frac{\partial\bar{y}_{k}^{j}}{\partial x^{\mu}} = 
-\sigma_j \left( \delta^j_\mu - \frac{k^j \sigma_\mu}{k \cdot \sigma} \right)\;,
$$

whence we obtain:

\be\label{deriv2}
 \frac{\partial\bar{y}_{k}^{0}}{\partial x^{0}} = \sigma_0 - \frac{k^0}{k \cdot \sigma}\;, \qquad\qquad
 \frac{\partial\bar{y}_{k}^{0}}{\partial x^{m}} = - \frac{k^0 \sigma_m}{ k \cdot \sigma}\;. 
\ee

The equations \eqref{deriv1} and \eqref{deriv2} can be written in a compact form as:

\begin{equation*}
 \frac{\partial\bar{y}_{k}^{\nu}}{\partial x^{\mu}}=\delta_{\mu}^{\nu}-\frac{k^{\nu}
 \sigma_{\mu}(\bar{y}_{k})}{k\cdot\sigma(\bar{y}_{k})} \equiv \Delta_{\mu}^{\nu}(\bar{y}_{k})\;.
\end{equation*}

Finally, using the chain rule for the derivative of an implicit function:

\begin{equation*}
\frac{\di}{\di x^\mu} g(x,y(x))= \frac{\partial}{\partial x^\mu} g(x,y(x))+ 
\Delta^{\; \nu}_\mu \frac{\partial g(x,y)}{\partial y^\nu}\Bigg|_{y=y(x)},
\end{equation*}

the equation \eqref{deltawig5} can be rewritten as:

\begin{eqnarray*}
&& \Delta W^{+}(x,k) =\frac{2}{\left(2\pi\right)^2}
\sum_{N=0}^{\infty}\frac{(-\ii)^{N}}{N!}
\left.\left[\partial^{q}_{\nu_{1}}\ldots\partial^{q}_{\nu_{N}}G^{\mu\nu}_k(q)\right]\right|_{q=0}
\sum_{M=0}^{N}\frac{N!(-1)^{M}}{M!(N-M)!} \left[\partial^{\nu_{M+1}}_{x}+
\Delta^{\alpha_{M+1}\rho_{M+1}}(\bar{y}_{k})\partial_{\rho_{M+1}}^{y}\right]\nonumber \\
 && \times\left.\ldots\left[\partial^{\nu_{n}}_{x}+\Delta^{\nu_n\rho_{n}}(\bar{y}_{k})
 \partial_{\rho_{n}}^{y}\right]\partial^{\nu_{1}}_{x}\cdots\partial^{\nu_{M}}_{x}
 \frac{n_{\mu}(y)}{|k\cdot\ n(y)|}\Delta\beta_{\nu}(y,x)\right|_{y=\bar{y}_k(x)}
 +\; {\rm analogous \; term \; for \; \Delta\zeta}\;.
\end{eqnarray*}

It is convenient to introduce the following differential operator:

\begin{equation}\label{D}
D_y(\bar y_k) \equiv  \Delta^{\nu\rho}(\bar y_k)
\partial_{\rho}^{y}\partial_{\nu}^{q}\;,
\end{equation}

By using the binomial theorem, the last expression can be finally recast as:

\begin{equation*}
\Delta W^{+}(x,k)=\frac{2}{\left(2\pi\right)^2}\sum_{N=0}^{\infty} \frac{(-\ii)^{N}}{N!}
\left(D_y\left(\bar{y}_k(x)\right)\right)^{N}
\left[ G^{\mu\nu}_k(q)\frac{n_{\mu}(y)}{|k\cdot n(y)|} \Delta\beta_\nu(y,x) \right] 
\Bigg|_{q=0,y=\bar{y}_k(x)} \hspace{-1.5cm} +\; {\rm analogous \; term \; for \; \Delta\zeta}\;,
\end{equation*}

which coincides with eq. \eqref{deltawigk} in the main text. Note that the differential operator \eqref{D} acts only on the square bracket and not on the projector $\Delta$ which is already computed on the intersection $\bar{y}_k(x)$ hence \eqref{D} never acts upon itself.

